import com.google.gson.*;
import ghidra.program.model.listing.*;
import ghidra.program.model.address.*;
import ghidra.program.model.symbol.*;
import ghidra.app.decompiler.*;
import ghidra.util.task.TaskMonitor;
import java.util.*;
import java.nio.charset.StandardCharsets;

/** One instance, accessed only by the owner thread. */
public final class RetkQueries implements AutoCloseable {
    final Program program; final TaskMonitor monitor;final String runId; final DecompInterface decompiler=new DecompInterface();
    public RetkQueries(Program p,TaskMonitor m){this(p,m,UUID.randomUUID().toString());}
    public RetkQueries(Program p,TaskMonitor m,String run){program=p;monitor=m;runId=run;if(!decompiler.openProgram(p))throw error("decompile_failed","Cannot open decompiler");}
    public static IllegalArgumentException error(String code,String message){return new IllegalArgumentException(code+": "+message);}
    public static String hex(Address a){return a.getAddressSpace().getName()+":0x"+a.getOffsetAsBigInteger().toString(16);}
    public static String str(JsonObject p,String k,String fallback){return p.has(k)&&!p.get(k).isJsonNull()?p.get(k).getAsString():fallback;}
    public static Address address(Program p,String text){try{if(text==null||!text.matches("(?:[A-Za-z_][A-Za-z0-9_.-]*:)?(?:0[xX])?[0-9a-fA-F]{1,16}"))throw new Exception();int colon=text.indexOf(':');AddressSpace space=colon<0?p.getAddressFactory().getDefaultAddressSpace():p.getAddressFactory().getAddressSpace(text.substring(0,colon));if(space==null)throw new Exception();String s=text.substring(colon+1).replaceFirst("^0[xX]","");Address a=space.getAddress(Long.parseUnsignedLong(s,16));if(!p.getMemory().contains(a))throw error("address_unmapped","Address is outside mapped memory");return a;}catch(IllegalArgumentException e){if(e.getMessage()!=null&&e.getMessage().startsWith("address_unmapped:"))throw e;throw error("address_unmapped","Invalid address");}catch(Exception e){throw error("address_unmapped","Invalid address");}}
    public Function function(JsonObject p){String s=str(p,"selector",str(p,"address",str(p,"name",null)));if(s==null)throw error("invalid_params","Function selector required");if(s.matches("(?:[A-Za-z_][A-Za-z0-9_.-]*:)?0[xX][0-9a-fA-F]{1,16}")){Function f=program.getFunctionManager().getFunctionAt(address(program,s));if(f==null)throw error("function_not_found","No function at exact entry");return f;}Function found=null;var it=program.getFunctionManager().getFunctions(true);while(it.hasNext()){Function f=it.next();if(f.getName().equals(s)||f.getName(true).equals(s)){if(found!=null)throw error("ambiguous_selector","More than one function has this name; use an address");found=f;}}if(found==null)throw error("function_not_found","No function matches selector");return found;}
    public JsonObject describe(Function f){JsonObject o=new JsonObject();o.addProperty("address",hex(f.getEntryPoint()));o.addProperty("name",f.getName());o.addProperty("qualifiedName",f.getName(true));o.addProperty("signature",f.getSignature().toString());o.addProperty("bodySize",f.getBody().getNumAddresses());JsonObject c=new JsonObject();for(var e:commentTypes().entrySet())c.add(e.getKey(),nullable(program.getListing().getComment(e.getValue(),f.getEntryPoint())));o.add("comments",c);return o;}
    public static Map<String,CommentType> commentTypes(){return Map.of("eol",CommentType.EOL,"pre",CommentType.PRE,"post",CommentType.POST,"plate",CommentType.PLATE,"repeatable",CommentType.REPEATABLE);}
    public static JsonElement nullable(String s){return s==null?JsonNull.INSTANCE:new JsonPrimitive(s);}
    int limit(JsonObject p,int def,int max){int n=p.has("limit")?p.get("limit").getAsInt():def;if(n<1||n>max)throw error("invalid_params","Limit must be between 1 and "+max);return n;}
    int offset(JsonObject p,String method,long revision){if(!p.has("cursor"))return 0;try{JsonObject c=JsonParser.parseString(new String(Base64.getUrlDecoder().decode(p.get("cursor").getAsString()),StandardCharsets.UTF_8)).getAsJsonObject();if(c.get("revision").getAsLong()!=revision)throw error("revision_conflict","Cursor revision changed");JsonObject binding=p.deepCopy();binding.remove("cursor");binding.remove("limit");if(!c.get("runId").getAsString().equals(runId)||!c.get("method").getAsString().equals(method)||!c.get("binding").equals(binding))throw error("invalid_cursor","Cursor session or query binding differs");int n=c.get("offset").getAsInt();if(n<0)throw new Exception();return n;}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw error("invalid_cursor","Invalid paging cursor");}}
    static class Window {final int offset,limit;int seen=0;final JsonArray rows=new JsonArray();Window(int o,int n){offset=o;limit=n;}boolean add(JsonObject row){if(seen++<offset)return false;rows.add(row);return rows.size()>limit;}}
    JsonObject page(Window window,JsonObject p,String method,long revision){JsonObject result=new JsonObject();JsonArray items=new JsonArray();for(int i=0;i<Math.min(window.rows.size(),window.limit);i++)items.add(window.rows.get(i));result.add("items",items);result.add("nextCursor",JsonNull.INSTANCE);if(window.rows.size()>window.limit){JsonObject c=new JsonObject(),binding=p.deepCopy();binding.remove("cursor");binding.remove("limit");c.addProperty("runId",runId);c.addProperty("method",method);c.addProperty("revision",revision);c.addProperty("offset",window.offset+window.limit);c.add("binding",binding);result.addProperty("nextCursor",Base64.getUrlEncoder().withoutPadding().encodeToString(c.toString().getBytes(StandardCharsets.UTF_8)));}return result;}
    public JsonObject execute(String method,JsonObject p,long revision)throws Exception {
        Window window=new Window(offset(p,method,revision),limit(p,100,1000));
        switch(method){
        case "functions.get":return describe(function(p));
        case "functions.list":{String q=str(p,"query","").toLowerCase(Locale.ROOT);var it=program.getFunctionManager().getFunctions(true);while(it.hasNext()){monitor.checkCancelled();Function f=it.next();if(f.getName(true).toLowerCase(Locale.ROOT).contains(q)&&window.add(describe(f)))break;}break;}
        case "instructions.list":{Address a=address(program,str(p,"address",str(p,"selector",null)));Address end=p.has("endAddress")?address(program,str(p,"endAddress",null)):null;if(end!=null&&(!a.getAddressSpace().equals(end.getAddressSpace())||end.compareTo(a)<0||end.getOffsetAsBigInteger().subtract(a.getOffsetAsBigInteger()).compareTo(java.math.BigInteger.valueOf(65536))>=0))throw error("invalid_params","Instruction range must be 1..65536 bytes in one address space");var it=program.getListing().getInstructions(a,true);while(it.hasNext()){monitor.checkCancelled();Instruction i=it.next();if(end!=null&&i.getAddress().compareTo(end)>0)break;if(end!=null&&i.getMaxAddress().compareTo(end)>0)throw error("invalid_params","Instruction crosses explicit end address");JsonObject row=new JsonObject();row.addProperty("address",hex(i.getAddress()));row.addProperty("text",i.toString());row.addProperty("length",i.getLength());if(window.add(row))break;}break;}
        case "references.list":{Address a=address(program,str(p,"address",null));String direction=str(p,"direction","to");if(!Set.of("to","from").contains(direction))throw error("invalid_params","Direction must be to or from");Iterable<Reference> refs=direction.equals("from")?Arrays.asList(program.getReferenceManager().getReferencesFrom(a)):()->program.getReferenceManager().getReferencesTo(a);for(Reference r:refs){monitor.checkCancelled();JsonObject row=new JsonObject();row.addProperty("from",hex(r.getFromAddress()));row.addProperty("to",hex(r.getToAddress()));row.addProperty("type",r.getReferenceType().toString());if(window.add(row))break;}break;}
        case "strings.search":{String q=str(p,"query","").toLowerCase(Locale.ROOT);var it=program.getListing().getDefinedData(true);while(it.hasNext()){monitor.checkCancelled();Data d=it.next();if(d.hasStringValue()){String s=String.valueOf(d.getValue());if(s.toLowerCase(Locale.ROOT).contains(q)){JsonObject row=new JsonObject();row.addProperty("address",hex(d.getAddress()));row.addProperty("value",s);if(window.add(row))break;}}}break;}
        case "memory.read":{Address a=address(program,str(p,"address",null));int n=p.has("length")?p.get("length").getAsInt():64;if(n<1||n>4096)throw error("invalid_params","Memory length must be 1..4096");byte[] bytes=new byte[n];int got=program.getMemory().getBytes(a,bytes);if(got!=n)throw error("address_unmapped","Range is not fully mapped");JsonObject result=new JsonObject();result.addProperty("address",hex(a));result.addProperty("hex",HexFormat.of().formatHex(bytes));return result;}
        case "functions.decompile":{Function f=function(p);int timeout=p.has("timeoutSeconds")?p.get("timeoutSeconds").getAsInt():60;if(timeout<1||timeout>300)throw error("invalid_params","Decompiler timeout must be 1..300 seconds");DecompileResults result=decompiler.decompileFunction(f,timeout,monitor);if(!result.decompileCompleted()||result.getDecompiledFunction()==null)throw error("decompile_failed",result.getErrorMessage());String[] lines=result.getDecompiledFunction().getC().split("\\n",-1);for(int i=0;i<lines.length;i++){JsonObject row=new JsonObject();row.addProperty("line",i+1);row.addProperty("text",lines[i]);if(window.add(row))break;}JsonObject o=page(window,p,method,revision);o.addProperty("address",hex(f.getEntryPoint()));return o;}
        default:throw error("method_not_found","Unsupported query method");}
        return page(window,p,method,revision);
    }
    public void flush(){decompiler.flushCache();}
    public void close(){decompiler.dispose();}
}
